import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.D7EuCHIT.js";const u=JSON.parse('{"title":"目录、歌词与分类接口","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/data.md","filePath":"plugins/data.md","lastUpdated":1791906173000}'),o={name:"plugins/data.md"};function n(s,a,d,c,l,p){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="目录、歌词与分类接口" tabindex="-1">目录、歌词与分类接口 <a class="header-anchor" href="#目录、歌词与分类接口" aria-label="Permalink to &quot;目录、歌词与分类接口&quot;">​</a></h1><p>媒体目录与歌词文档都是 revision 限定的数据，先读取版本和曲目标识，再读取当前范围。不要把目录行、曲目 ID 和队列行混为一谈。</p><h2 id="媒体源" tabindex="-1">媒体源 <a class="header-anchor" href="#媒体源" aria-label="Permalink to &quot;媒体源&quot;">​</a></h2><p>媒体源实现 <code>LyraMediaProviderV3</code>，处理 collection/search/audio/cover/lyrics 请求。通过 sink 发布 <code>LyraMediaDescriptorV3</code>，其中包含完整 UTF-8 标题、艺术家、专辑、流派、文件夹与资源位置。异步结果必须携带原请求 ID；取消或失效请求不能发布。</p><p>宿主 <code>LyraMediaContextV3</code> 提供提供者发现、集合读取、当前曲目与队列操作。数据按请求和 revision 读取；字符串在当前帧边界或 revision 变化前借用。不要把旧短记录或同步目录接口作为另一条数据路径。具体流程见<a href="/LyraPlayer-docs-site/plugins/media">媒体请求接口</a>。</p><h2 id="歌词" tabindex="-1">歌词 <a class="header-anchor" href="#歌词" aria-label="Permalink to &quot;歌词&quot;">​</a></h2><p>LyraLyricsInterfaceV3 提供 revision、track_id、count、line、word、text。line 的 flags bit0 为 RTL、bit1 为无时间轴。时间是微秒，word.units 是 UTF-16 单元，用于测量对齐，不是 UTF-8 字节数。</p><p>text kind：0 正文、1 译文、2 音标、3 和声、4 逐字文本、5 逐字音标；part 为和声/词索引。缓冲不足不写，返回含 NUL 所需长度。</p><p>调用者不能包含私有 <code>document.hpp</code>，也不能自行把文档工作线程指针送给渲染器。异步歌词结果必须匹配当前曲目和 generation。嵌入文本读入有预算，不读取字幕包、不解密 krc1、不记录正文日志。</p><h2 id="分类" tabindex="-1">分类 <a class="header-anchor" href="#分类" aria-label="Permalink to &quot;分类&quot;">​</a></h2><p>profile-classification 提供 LyraClassificationRulesV3。genres 返回换行分隔标签；language 接收正文、标题与 has_lyrics；language_label 负责显示标签。规则改变推进 revision。</p><p>默认流派来自真实标签，未知自定义标签保留原名；文件夹按完整位置区分。语言优先正文而不是译文/注音，只有无可读歌词才用歌名。有歌词但不足以识别时回退未知，不把短标题猜成准确语言。</p><p>默认识别是本地规则，不是全语言模型。外部插件可以替换分类策略，但应声明性能、网络与隐私行为；默认搜索和分类不会上传曲库或查询词。</p>',13)])])}const _=e(o,[["render",n]]);export{u as __pageData,_ as default};
